import sys, json, subprocess, numpy as np, wave, base64
SR=44100
def ft2call(tool,args):
    return subprocess.run(["ft2","call",tool,json.dumps(args)],capture_output=True,text=True).stdout.strip()
def tone(f,dur=1.0,amp=0.5):
    t=np.arange(int(dur*SR))/SR
    y=np.sin(2*np.pi*f*t)*amp
    y[:800]*=np.linspace(0,1,800); y[-800:]*=np.linspace(1,0,800)
    return base64.b64encode(np.int16(np.round(y*32767)).tobytes()).decode()
def measure(path):
    w=wave.open(path); n=w.getnframes()
    d=np.frombuffer(w.readframes(n),dtype='<i2').astype(np.float64)/32767
    d=d.reshape(-1,w.getnchannels())[:,0]
    idx=np.where(np.abs(d)>0.05)[0]
    if len(idx)<8000: return None
    st=idx[0]+int(0.02*SR); seg=d[st:st+16384]
    seg=seg-seg.mean()
    F=np.abs(np.fft.rfft(seg*np.hanning(len(seg)),16*len(seg))); f=np.fft.rfftfreq(16*len(seg),1/SR)
    return float(f[np.argmax(F)])
def probe(val, finetune=None, rel=None, f=440.0):
    ft2call("module_new",{"channels":1,"name":"P"}); ft2call("song_set",{"bpm":128,"speed":6})
    ft2call("pattern_set_length",{"pattern":0,"rows":16})
    ft2call("sample_create_from_pcm",{"instrument":1,"sample":0,"name":"S","pcm":tone(f,0.8)})
    a={"instrument":1,"sample":0}
    if finetune is not None: a["finetune"]=finetune
    if rel is not None: a["relative_note"]=rel
    if len(a)>1: ft2call("sample_set",a)
    ft2call("pattern_set_cell",{"pattern":0,"row":0,"channel":0,"note":val,"instrument":1})
    ft2call("module_render",{"path":"/workspace/work/probe.wav","rate":44100,"loops":0,"stop":1})
    return measure('/workspace/work/probe.wav')
tests=[("val78 ft0",78,0,None),("val78 ft-22",78,-22,None),("val78 ft-13",78,-13,None),
       ("val78 ft-100",78,-100,None),("val78 ft+22",78,22,None),
       ("val78 rel69",78,None,69),("val78 rel57",78,None,57),("val69 rel57",69,None,57),
       ("val90 ft0",90,0,None)]
for lab,v,ft,rel in tests:
    fp=probe(v,ft,rel)
    print("%-14s -> %s  (st from 440: %s)"%(lab, "%.2f"%fp if fp else "err", "%+.2f"%(12*np.log2(fp/440)) if fp else "-"))
