{"command": "cd /workspace/work && cat > behavior2.py << 'PYEOF'
import sys, json, subprocess, numpy as np, wave, base64
SR=44100
def ft2(tool,args):
    r=subprocess.run(["ft2","call",tool,json.dumps(args)],capture_output=True,text=True)
    s=r.stdout.strip()
    try:
        o=json.loads(s); return o.get("isError",False), o["content"][0]["text"]
    except Exception: return True, s
def render(stop):
    return ft2("module_render",{"path":"/workspace/work/x.wav","rate":44100,"loops":0,"stop":stop})
def rms_first(stop=0.6):
    render(stop)
    w=wave.open('/workspace/work/x.wav'); n=w.getnframes()
    d=np.frombuffer(w.readframes(n),dtype='<i2').astype(np.float64)/32767
    d=d.reshape(-1,w.getnchannels())
    seg=d[int(0.05*SR):int(0.45*SR)]
    return round(float(np.sqrt(np.mean(seg**2))),5), round(float(np.max(np.abs(seg))),5)
def setup(note=78, vol=None, eff=None, par=None, rows=16, ch=2):
    ft2("module_new",{"channels":ch,"name":"T"}); ft2("song_set",{"bpm":128,"speed":6})
    ft2("pattern_set_length",{"pattern":0,"rows":rows})
    ft2("sample_load",{"path":"/workspace/work/samples/pad_a.wav","instrument":1,"sample":0})
    j=json.load(open('/workspace/work/samples/pad_a.json'))
    ft2("sample_set",{"instrument":1,"sample":0,"loop_start":j["loop_start"],"loop_length":j["loop_length"],"flags":1,"volume":64})
    a={"pattern":0,"row":0,"channel":0,"note":note,"instrument":1}
    if vol is not None: a["volume"]=vol
    if eff is not None: a["effect"]=eff; a["effect_param"]=par
    ft2("pattern_set_cell",a)
print("=== volume column ===")
for v in [None,0,16,32,48,64,80,96,100,127,255,-1]:
    setup(vol=v)
    try: print("  vol",v,rms_first())
    except Exception as e: print("  vol",v,"ERR",e)
print("=== effect A (10) fine tune, param 0/128/168/228/242/40, note 78 (440*1.0125=445.5) ===")
for p in [0,128,168,228,242,40]:
    setup(eff=10,par=p,rows=8)
    render(0.6)
    w=wave.open('/workspace/work/x.wav'); n=w.getnframes()
    d=np.frombuffer(w.readframes(n),dtype='<i2').astype(np.float64)/32767
    d=d.reshape(-1,w.getnchannels())[:,0]
    idx=np.where(np.abs(d)>0.05)[0]
    if len(idx)>20000:
        st=idx[0]+3000; seg=d[st:st+16384]-np.mean(d[st:st+16384])
        N=len(seg); F=np.abs(np.fft.rfft(seg*np.hanning(N),16*N)); f=np.fft.rfftfreq(16*N,1/SR)
        k=int(np.argmax(F)); print("  param %-4d rms %.3f  %.3f Hz (%+.1f cents vs 445.5)"%(p,np.sqrt(np.mean(seg**2)),f[k],1200*np.log2(f[k]/445.5)))
    else:
        print("  param %-4d SILENT"%p)
print("=== effect E (14) vol slide: param 40/80/64/240, start vol 10 ===")
for p in [40,80,64,240]:
    setup(eff=14,par=p,vol=10,rows=32)
    print("  param",p,rms_first(1.2))
PYEOF
